const scraper=new DattebayoBRScraper;async function runTests(){console.log("🧪 Iniciando testes do scraper Dattebayo BR...\n");try{console.log("📍 Teste 1: Busca por 'Naruto'");const searchResults=await scraper.search("Naruto");if(console.log(`✓ Encontrados ${searchResults.length} resultados`),searchResults.length>0&&(console.log(`  - Primeiro resultado: ${searchResults[0].title}`),console.log(`  - URL: ${searchResults[0].url}\n`)),searchResults.length>0){console.log("📍 Teste 2: Obter episódios");const episodes=await scraper.getEpisodes(searchResults[0].id);if(console.log(`✓ Encontrados ${episodes.length} episódios`),episodes.length>0){console.log(`  - Primeiro episódio: ${episodes[0].title}`),console.log(`  - Número: ${episodes[0].number}\n`),console.log("📍 Teste 3: Obter streams");const streams=await scraper.getStreams(episodes[0].url);console.log(`✓ Encontrados ${streams.length} streams`),streams.length>0&&streams.forEach(((stream,idx)=>{console.log(`  - Stream ${idx+1}: ${stream.quality} (${stream.type})`)}))}}console.log("\n✅ Testes completados com sucesso!")}catch(error){console.error("❌ Erro durante os testes:",error)}}require.main===module&&runTests(),module.exports=runTests;